function makeSessionFilename(now = new Date()): string {
	const ts = now.toISOString().replace(/[:.]/g, "-");
	return `${ts}_${randomUUID()}.jsonl`;
}

export function createPiSessionFilePath(sessionDir: string, agentName: string): string {
	return join(agentSessionDir(sessionDir, agentName), makeSessionFilename());
}

edits.newText:
export function createPiSessionFilePath(sessionDir: string, agentName: string, cwd: string): string {
	const sm = SessionManager.create(cwd, agentSessionDir(sessionDir, agentName));
	const path = sm.getSessionFile();
	if (!path) {
		throw new Error(`Could not create session file for agent "${agentName}"`);
	}
	return path;
}

edits.oldText:
export function resolveSession(
	sessionDir: string,
	agentName: string,
	context: DispatchContext,
): SessionResolution {
	const dir = agentSessionDir(sessionDir, agentName);
	if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

	if (context === "fresh") {
		return {
			piSessionFile: createPiSessionFilePath(sessionDir, agentName),
			shouldContinue: false,
		};
	}

	const latest = latestPiSessionFilePath(sessionDir, agentName);
	if (latest) {
		return { piSessionFile: latest, shouldContinue: true };
	}

	return {
		piSessionFile: createPiSessionFilePath(sessionDir, agentName),
		shouldContinue: false,
	};
}

edits.newText:
export function resolveSession(
	sessionDir: string,
	agentName: string,
	context: DispatchContext,
	cwd: string,
): SessionResolution {
	const dir = agentSessionDir(sessionDir, agentName);
	if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

	if (context === "fresh") {
		return {
			piSessionFile: createPiSessionFilePath(sessionDir, agentName, cwd),
			shouldContinue: false,
		};
	}

	const hadExisting = Boolean(latestPiSessionFilePath(sessionDir, agentName));
	const sm = SessionManager.continueRecent(cwd, dir);
	const piSessionFile = sm.getSessionFile();
	if (!piSessionFile) {
		throw new Error(`Could not resolve session file for agent "${agentName}"`);
	}

	return {
		piSessionFile,
		shouldContinue: hadExisting,
	};
}

