import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from "fs";
import { join } from "path";
import { createRequire } from "module";
import type { AgentSession, DispatchContext, TokenUsage } from "./types.ts";

interface PiSessionManagerStatic {
	create(cwd: string, sessionDir?: string): { getSessionFile(): string | undefined };
	continueRecent(cwd: string, sessionDir?: string): { getSessionFile(): string | undefined };
}

function loadPiSessionManager(): PiSessionManagerStatic {
	const require = createRequire(import.meta.url);
	const candidates = [
		process.env.PI_CODING_AGENT_SESSION_MANAGER_PATH,
		"/home/lmingari/.npm-global/lib/node_modules/@mariozechner/pi-coding-agent/dist/core/session-manager.js",
		join(process.cwd(), "node_modules", "@mariozechner", "pi-coding-agent", "dist", "core", "session-manager.js"),
	].filter((v): v is string => Boolean(v));

	for (const p of candidates) {
		try {
			if (!existsSync(p)) continue;
			const mod = require(p);
			if (mod?.SessionManager) return mod.SessionManager as PiSessionManagerStatic;
		} catch {
			// try next candidate
		}
	}

	throw new Error(
		"Could not load pi SessionManager. Set PI_CODING_AGENT_SESSION_MANAGER_PATH " +
		"to .../pi-coding-agent/dist/core/session-manager.js"
	);
}

