test("createPiSessionFilePath uses pi SessionManager naming and matching header", () => {
	const root = mkdtempSync(join(tmpdir(), "pi-session-files-"));
	const path = createPiSessionFilePath(root, "agent1", process.cwd());
	const firstLine = readFileSync(path, "utf-8").split(/\r?\n/)[0];
	const header = JSON.parse(firstLine);

	assert.equal(header.type, "session");
	assert.equal(typeof header.id, "string");
	assert.equal(typeof header.timestamp, "string");

	const { prefix, uuid } = parseFilename(basename(path));
	assert.equal(uuid, header.id);
	assert.equal(prefix, timestampToFilenamePrefix(header.timestamp));
});

