function seedRunsFromExistingSessions(): number {
	let restored = 0;
	for (const member of GROUP.members) {
		const def = agentIndex.get(member.toLowerCase());
		if (!def) continue;
		const files = listPiSessionFiles(sessionDir, member);
		for (const file of files) {
			const header = readSessionHeader(file);
			if (!header?.id) continue;
			if (runs.has(header.id)) continue;

			const ts = Date.parse(header.timestamp || "") || Date.now();
			const request: DispatchRequest = {
				agent: def.name,
				task: "[restored from existing session]",
				inputs: [],
				output: GROUP.overrides?.[def.name]?.output ?? GROUP.defaults.output,
				context: GROUP.overrides?.[def.name]?.context ?? GROUP.defaults.context,
				terminal: GROUP.defaults.terminal,
				ipc: { type: "fifo", path: "", openTimeoutMs: GROUP.defaults.ipc.openTimeoutMs },
				sessionDir,
				cwd,
			};

			runs.set(header.id, {
				runId: header.id,
				sessionId: header.id,
				sessionFile: file,
				def,
				request,
				resolvedOutputPath: null,
				status: "complete",
				startedAt: ts,
				endedAt: ts,
				output: "",
				lastWork: `restored from ${file.split("/").pop()}`,
				toolCount: 0,
				contextPct: 0,
				runCount: 1,
				elapsed: 0,
			});
			restored += 1;
		}
	}
	return restored;
}

