import { readFileSync, existsSync, openSync, writeSync, closeSync } from "fs";

function parseHeader(sessionFile) {
	if (!sessionFile || !existsSync(sessionFile)) return {};
	try {
		const firstLine = readFileSync(sessionFile, "utf-8").split(/\r?\n/, 1)[0];
		const header = JSON.parse(firstLine);
		if (header?.type !== "session") return {};
		return {
			sessionId: typeof header.id === "string" ? header.id : undefined,
			timestamp: typeof header.timestamp === "string" ? header.timestamp : undefined,
		};
	} catch {
		return {};
	}
}

function sendIpc(msg) {
	const fifoPath = process.env.PI_IPC_FIFO;
	if (!fifoPath) return;
	try {
		const fd = openSync(fifoPath, "w");
		writeSync(fd, JSON.stringify(msg) + "\n", null, "utf-8");
		closeSync(fd);
	} catch {
		// Best-effort bridge only.
	}
}

function emitSessionUpdate(ctx, event) {
	const runId = process.env.PI_SUBAGENT_RUN_ID;
	if (!runId) return;
	const sessionFile = ctx.sessionManager.getSessionFile() || undefined;
	const { sessionId, timestamp } = parseHeader(sessionFile);
	sendIpc({
		type: "session_update",
		runId,
		sessionId,
		sessionFile,
		timestamp,
		reason: event?.reason,
	});
}

export default function (pi) {
	pi.on("session_start", async (event, ctx) => {
		emitSessionUpdate(ctx, event);
	});

	// Some pi versions expose this directly; in others session_start(reason=resume/new/fork)
	// is the canonical post-switch event.
	pi.on("session_switch", async (event, ctx) => {
		emitSessionUpdate(ctx, event);
	});
}

